const isFactor = { A: P(6) === 0, B: P(4) === 0, C: Pu(-4) === 0, D: P(-2) === 0 };
const ok = Object.keys(isFactor).filter(k => isFactor[k]);
return ok.length === 1 ? ok[0] : null;

const xs = [-5, 0, 1, 3, 7.5];
const eq = (f, g) => xs.every(x => Math.abs(f(x) - g(x)) < 1e-9);
const p1 = eq(x => 2 * x * x - 8, x => 2 * (x * x - 4));
const p2 = eq(x => 2 * (x * x - 4), x => 2 * (x - 2) * (x + 2));
const p3 = eq(x => x * x - 4 * x + 4, x => (x - 2) * (x + 2));
const p4 = eq(x => 2 * (x - 2) * (x + 2) / ((x - 2) * (x + 2)), x => 2);
const i = [p1, p2, p3, p4].indexOf(false);
return i < 0 ? null : 'ABCD'[i];

const s = 34 / 2, d2 = 13 * 13;
const v = (s * s - d2) / 2;
const disc = s * s - 4 * v;
const a = (s + Math.sqrt(disc)) / 2, b = s - a;
if (Math.abs(a * a + b * b - d2) > 1e-9) return null;
const alts = { A: 30, B: 60, C: 72.25, D: 120 };
const ok = Object.keys(alts).filter(k => Math.abs(alts[k] - v) < 1e-9);
return ok.length === 1 ? ok[0] : null;

