const neg = k => (2 * k + 4) / (k - 3) < 0;
const alts = { A: k => k > -2 && k < 3, B: k => k < -2 || k > 3, C: k => k > 3, D: k => k < 3 };
const ks = [];
for (let i = -400; i <= 400; i++) { const k = i / 20; if (k !== 3) ks.push(k); }
const ok = Object.keys(alts).filter(x => ks.every(k => alts[x](k) === neg(k)));
return ok.length === 1 ? ok[0] : null;

const cost = t => 900 + 15 * (t - 60);
const alts = { A: t => 900 + 15 * t <= 4500, B: t => 15 * (t - 60) <= 4500, C: t => 900 + 15 * (t - 60) >= 4500, D: t => 900 + 15 * (t - 60) <= 4500 };
const ts = [];
for (let t = 61; t <= 400; t++) ts.push(t);
const ok = Object.keys(alts).filter(k => ts.every(t => alts[k](t) === (cost(t) <= 4500)));
return ok.length === 1 ? ok[0] : null;

const det = 3 * 5 - 2 * 2;
const p = (14400 * 5 - 2 * 14000) / det;
const t = (3 * 14000 - 2 * 14400) / det;
const v = p + t;
const alts = { A: 2800, B: 4000, C: 5200, D: 5680 };
