const sols = [];
for (let N = 1; N <= 300; N++) {
  if (N % 4 !== 3 || (N + 2) % 5 !== 0) continue;
  if (Math.floor(N / 4) === (N + 2) / 5 + 2) sols.push(N);
}
if (sols.length !== 1) return null;
const v = sols[0];
const alts = { A: 43, B: 47, C: 63, D: 65 };
const ok = Object.keys(alts).filter(k => Math.abs(alts[k] - v) < 1e-9);
return ok.length === 1 ? ok[0] : null;

